create extension if not exists pgcrypto;
create table if not exists communes(id uuid primary key default gen_random_uuid(), name text unique not null, active boolean default true, created_at timestamptz default now());
create table if not exists people(id uuid primary key default gen_random_uuid(), document_type text default 'CC', document_number text unique not null, first_name text not null, last_name text not null, phone text not null, email text, address text, residence_commune_id uuid references communes(id), residence_neighborhood text, self_declared_leader boolean default false, validated_leader boolean default false, privacy_accepted_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists person_territories(id uuid primary key default gen_random_uuid(), person_id uuid references people(id) on delete cascade, commune_id uuid references communes(id), neighborhood text, notes text, created_at timestamptz default now());
create table if not exists electoral_information(id uuid primary key default gen_random_uuid(), person_id uuid unique references people(id) on delete cascade, voting_commune_id uuid references communes(id), voting_neighborhood text, voting_place text, voting_table text, verified boolean default false, verified_at timestamptz, updated_at timestamptz default now());
create table if not exists meetings(id uuid primary key default gen_random_uuid(), public_token text unique not null default upper(substr(encode(gen_random_bytes(6),'hex'),1,8)), name text not null, meeting_date date not null, meeting_time time, commune_id uuid references communes(id), neighborhood text, place text, notes text, status text not null default 'PROGRAMADA' check(status in ('PROGRAMADA','ABIERTA','FINALIZADA','CANCELADA')), allow_qr boolean default true, created_at timestamptz default now());
create table if not exists attendances(id uuid primary key default gen_random_uuid(), meeting_id uuid references meetings(id) on delete cascade, person_id uuid references people(id) on delete cascade, source text default 'QR', created_at timestamptz default now(), unique(meeting_id,person_id));
create table if not exists prospects(id uuid primary key default gen_random_uuid(), full_name text not null, phone text not null, email text, comments text, status text default 'NUEVO', privacy_accepted_at timestamptz not null default now(), created_at timestamptz default now());
create table if not exists commitments(id uuid primary key default gen_random_uuid(), leader_id uuid references people(id), meeting_id uuid references meetings(id), description text not null, status text default 'ABIERTO' check(status in ('ABIERTO','EN_PROCESO','ATENDIDO','CANCELADO')), due_date date, notes text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists site_settings(id int primary key default 1 check(id=1), candidate_name text default 'CANDIDATO', candidate_role text, profile_label text default 'CONOCE A NUESTRO CANDIDATO', profile_title text default 'Experiencia que transforma', profile_intro text default 'Una trayectoria construida junto a la comunidad.', candidate_image_url text, primary_color text default '#5b214e', secondary_color text default '#f7eef5', accent_color text default '#d4af37', electoral_url text, instagram text, facebook text, tiktok text, x_url text, updated_at timestamptz default now());
create table if not exists featured_content(id uuid primary key default gen_random_uuid(), title text not null, label text, body text, image_url text, button_text text, button_url text, sort_order int default 1, active boolean default true, created_at timestamptz default now());
create table if not exists profile_sections(id uuid primary key default gen_random_uuid(), title text not null, body text not null, icon text, sort_order int default 1, active boolean default true);
create table if not exists offices(id uuid primary key default gen_random_uuid(), name text not null, address text not null, active boolean default true);
insert into site_settings(id) values(1) on conflict do nothing;
insert into communes(name) select 'Comuna '||g from generate_series(1,13) g on conflict do nothing;
insert into featured_content(title,label,body,button_text,button_url,sort_order) values ('Construimos territorio con la comunidad','CERCA DE LA GENTE','Experiencia, gestión social y presencia real en cada sector.','Conoce el trabajo','#perfil',1) on conflict do nothing;
insert into profile_sections(title,body,sort_order) values ('Experiencia','Contenido administrable sobre trayectoria profesional y comunitaria.',1),('Gestión social','Proyectos, acciones y resultados destacados con la comunidad.',2),('Visión','Un territorio construido escuchando a la comunidad.',3) on conflict do nothing;
